// Cloudflare Worker entry: the OpenNext app handler plus a Cron Trigger that
// runs SolveANeed's background jobs (notification delivery, offer expiry, task
// auto-acceptance) through the protected /api/jobs/run route.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
}

const worker = {
  fetch: handler.fetch,
  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) return;
    const req = new Request("https://worker.internal/api/jobs/run", {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

export default worker;
